# Check if a file is encoded in UTF-8
def is_utf8_encoded(file_content):
    try:
        file_content.decode('utf-8')
        return True
    except UnicodeDecodeError:
        return False

# Example usage
file_content = b'Hello World'  # Example byte content
print(is_utf8_encoded(file_content))  # Should print True
